constraints:
1 <= sum, N <= 10^{3}

expected time complexity: O(sum*N)
expected auxiliary space: O(sum)

standard_solution_code:
class Solution:

	def count(self, coins, N, Sum):
		table = [0 for k in range(sum + 1)]
		table[0] = 1
		for i in range(0, N):
			for j in range(coins[i], sum + 1):
				table[j] += table[j - coins[i]]
		return table[Sum]
